solution.tournament.zig:
const std = @import("std");
const Team = struct {
    name: []const u8,
    w: usize = 0,
    d: usize = 0,
    l: usize = 0,
    fn points(s: Team) usize {
        return s.w * 3 + s.d;
    }
};
fn index(teams: *std.array_list.Managed(Team), name: []const u8) !usize {
    for (teams.items, 0..) |team, i| {
        if (std.mem.eql(u8, team.name, name)) return i;
    }
    try teams.append(.{ .name = name });
    return teams.items.len - 1;
}
pub fn tally(a: std.mem.Allocator, input: []const u8) ![]u8 {
    var teams = std.array_list.Managed(Team).init(a);
    defer teams.deinit();
    var lines = std.mem.splitScalar(u8, input, '\n');
    while (lines.next()) |line| {
        var fields = std.mem.splitScalar(u8, line, ';');
        const first = fields.next() orelse continue;
        const second = fields.next() orelse continue;
        const result = fields.next() orelse continue;
        if (fields.next() != null) continue;
        const win = std.mem.eql(u8, result, "win");
        const loss = std.mem.eql(u8, result, "loss");
        const draw = std.mem.eql(u8, result, "draw");
        if (!win and !loss and !draw) continue;
        const x = try index(&teams, first);
        const y = try index(&teams, second);
        if (win) {
            teams.items[x].w += 1;
            teams.items[y].l += 1;
        } else if (loss) {
            teams.items[x].l += 1;
            teams.items[y].w += 1;
        } else {
            teams.items[x].d += 1;
            teams.items[y].d += 1;
        }
    }
    std.mem.sort(Team, teams.items, {}, struct {
        fn less(_: void, x: Team, y: Team) bool {
            return if (x.points() != y.points()) x.points() > y.points() else std.mem.order(u8, x.name, y.name) == .lt;
        }
    }.less);
    var out = std.array_list.Managed(u8).init(a);
    errdefer out.deinit();
    try out.appendSlice("Team                           | MP |  W |  D |  L |  P");
    for (teams.items) |team| {
        const row = try std.fmt.allocPrint(a, "\n{s: <30} | {d: >2} | {d: >2} | {d: >2} | {d: >2} | {d: >2}", .{ team.name, team.w + team.d + team.l, team.w, team.d, team.l, team.points() });
        defer a.free(row);
        try out.appendSlice(row);
    }
    return out.toOwnedSlice();
}

